"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["25426"],{82683(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.configuracao_do_recurso_da_etapa.prazo_em_fracao_de_dia_util","status":422,"titulo":"O prazo do recurso em dias \xfateis exige n\xfamero inteiro"},"descricao":{"codigo":"uniplus.selecao.configuracao_do_recurso_da_etapa.prazo_em_fracao_de_dia_util","requisitos":["UNI-REQ-0113"],"oQueAconteceu":["O prazo declarado pela configura\xe7\xe3o do recurso de uma etapa est\xe1 em **dias \xfateis**, mas com valor fracionado, como 1,5. Isso vale para os dois prazos da configura\xe7\xe3o: o de **interposi\xe7\xe3o**, na 1\xaa inst\xe2ncia, e o da **2\xaa inst\xe2ncia**. A recusa sai com **422**, nada \xe9 gravado, e o campo recusado \xe9 `etapas[i].recursos[j].prazoValor` (interposi\xe7\xe3o) ou `etapas[i].recursos[j].prazoSegundaInstanciaValor` (2\xaa inst\xe2ncia), em que `i` \xe9 a posi\xe7\xe3o da etapa e `j`, a do recurso na etapa.","A mensagem da resposta diz qual dos prazos foi recusado: \\"O prazo de interposi\xe7\xe3o em dias \xfateis exige n\xfamero inteiro. Para prazo menor que um dia, informe em horas.\\" ou a mesma frase com \\"prazo da 2\xaa inst\xe2ncia\\". O dia \xfatil \xe9 contado inteiro: cada dia n\xe3o \xfatil \xe9 pulado, e uma parte de dia \xfatil n\xe3o tem como ser contada (UNI-REQ-0113)."],"comoResolver":["Declare o prazo em dias \xfateis com valor inteiro, ou declare em horas o prazo que o edital prev\xea. S\xf3 avan\xe7am o rel\xf3gio as horas situadas em dia \xfatil."],"ondeAparece":["Defini\xe7\xe3o de etapas do processo seletivo","Leitura do documento de configura\xe7\xe3o do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Configuracao do recurso da etapa"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);